"""Prospective TRAIN-only human-source quality counts, zero model/tokenizer use."""
import collections, hashlib, json, pathlib, statistics
base=pathlib.Path('/workspace/daily-conversation-source-audit');m=json.loads((base/'human-source-acquisition.json').read_text());root=base/'human-only-raw/train';folds=json.loads((base/'prospective-speaker-folds.json').read_text())['speakerFolds']
lengths=[];dialogue_lengths=[];hashes=collections.Counter();empty=masked=controls=consecutive=0;masked_dialogues=0;train_speakers=set();turns=0
for item in m['records']:
 if item['fold']!='train':continue
 path=root/pathlib.PurePosixPath(item['sourcePath']).name;raw=path.read_bytes();assert hashlib.sha256(raw).hexdigest()==item['sha256'];d=json.loads(raw);assert all(folds[s]=='train' for s in d['interlocutors']);train_speakers.update(d['interlocutors']);previous=None;has_mask=False;sequence=[]
 for u in d['utterances']:
  assert isinstance(u['text'],str) and u['interlocutor_id'] in d['interlocutors'];text=u['text'];lengths.append(len(text));empty+=not text.strip();is_mask='＊＊' in text;masked+=is_mask;has_mask|=is_mask;controls+=any(ord(c)<32 and c not in '\n\t\r' for c in text);consecutive+=previous==u['interlocutor_id'];previous=u['interlocutor_id'];sequence.append([d['interlocutors'].index(u['interlocutor_id']),text]);turns+=1
 masked_dialogues+=has_mask;dialogue_lengths.append(len(d['utterances']));hashes[hashlib.sha256(json.dumps(sequence,ensure_ascii=False,separators=(',',':')).encode()).hexdigest()]+=1
report={'scope':'Prospective TRAIN only; not used by R26; no heldout text inspected by this audit','sourceCommit':m['sourceCommit'],'trainingDialogues':len(dialogue_lengths),'trainingUtterances':turns,'trainingCharacters':sum(lengths),'meanCharactersPerUtterance':statistics.mean(lengths),'medianCharactersPerUtterance':statistics.median(lengths),'meanUtterancesPerDialogue':statistics.mean(dialogue_lengths),'maxUtterancesPerDialogue':max(dialogue_lengths),'emptyUtterances':empty,'utterancesWithSourceRedactionMask':masked,'dialoguesWithSourceRedactionMask':masked_dialogues,'utterancesWithUnexpectedControlCharacters':controls,'adjacentSameSpeakerMessages':consecutive,'observedTrainSpeakers':len(train_speakers),'exactDialogueDuplicateExcess':sum(v-1 for v in hashes.values()),'sourceTextRewrittenOrFiltered':False,'tokenizerExecuted':False,'modelExecuted':False,'modelTrainingUpdates':0,'developmentAndTestReadByAudit':False,'crossFoldNearDuplicateAuditPending':True}
(base/'prospective-train-quality.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report),flush=True)
